  directedness text NOT NULL CHECK (directedness IN ('directed', 'ambient')),
  priority text NOT NULL CHECK (priority IN ('CRITICAL', 'HIGH', 'NORMAL', 'LOW')),
  group_scope text NOT NULL CHECK (group_scope IN ('entity', 'type_day')),
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  default_push bigint NOT NULL DEFAULT 0,
  default_telegram bigint NOT NULL DEFAULT 0,
  UNIQUE (organization_id, code)
);

CREATE TABLE notifications (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  user_id bigint NOT NULL,
  type_code text NOT NULL,
  title_fa text NOT NULL,
  body_fa text,
  entity_type text,
  entity_id bigint,
  group_key text NOT NULL,
  priority text NOT NULL,
  created_at text NOT NULL,
  seen_at text,
  read_at text,
  source_event_id bigint,
  source_rule_run_id bigint,
  push_flushed_at text,
  tg_flushed_at text,
  ref_id bigint
);

CREATE TABLE objection_cards (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint,
  outcome_code text NOT NULL,
  customer_type text,
  title_fa text NOT NULL,
  script_fa text NOT NULL,
  module_slug text,
  active bigint NOT NULL DEFAULT 1,
  updated_at text NOT NULL,
  UNIQUE (organization_id, outcome_code, customer_type)
);

CREATE TABLE order_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  order_id bigint NOT NULL,
  from_status text,
  to_status text NOT NULL,
  action text NOT NULL,
  actor_user_id bigint,
  reason_code_id bigint,
  note text,
  device_time text,
  created_at text NOT NULL,
  impersonated_by bigint
);

CREATE TABLE order_lines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id bigint NOT NULL,
  product_id bigint NOT NULL,
  packaging_id bigint NOT NULL,
  packs_ordered double precision NOT NULL,
  packs_delivered double precision,
  unit_price_toman bigint NOT NULL,
  unit_cost_toman bigint NOT NULL DEFAULT 0,
  qty_per_pack double precision NOT NULL,
  kg_per_base_unit double precision NOT NULL,
  price_id bigint,
  is_reversal bigint NOT NULL DEFAULT 0,
  reverses_line_id bigint,
  created_at text NOT NULL
);

CREATE TABLE orders (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_no text NOT NULL,
  customer_id bigint NOT NULL,
  group_id bigint,
  salesperson_user_id bigint,
  status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PENDING_REVIEW', 'PENDING_CREDIT', 'ON_HOLD', 'CONFIRMED', 'PLANNED', 'READY', 'OUT_FOR_DELIVERY', 'DELIVERED', 'PARTIALLY_DELIVERED', 'DELIVERY_FAILED', 'CLOSED', 'CANCELLED', 'RETURNED')),
  order_type text NOT NULL DEFAULT 'SALE',
  priority text NOT NULL DEFAULT 'NORMAL',
  offline bigint NOT NULL DEFAULT 0,
  order_date text NOT NULL,
  delivered_at text,
  payment_status text NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid', 'partial', 'paid')),
  paid_toman bigint NOT NULL DEFAULT 0,
  credit_override_by bigint,
  credit_hold bigint NOT NULL DEFAULT 0,
  notes text,
  created_by bigint NOT NULL,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  organization_id bigint,
  requested_day text,
  requested_kind text CHECK (requested_kind IN ('soonest', 'week_offset', 'exact_date')),
  client_uuid text,
  kg_total double precision,
  total_toman bigint,
  cost_toman bigint,
  UNIQUE (organization_id, order_no)
);

CREATE TABLE organizations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  slug text UNIQUE NOT NULL,
  plan text NOT NULL DEFAULT 'standard',
  active bigint NOT NULL DEFAULT 1,
  contact_name text,
  contact_phone text,
  created_at text NOT NULL
);

CREATE TABLE packagings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id bigint NOT NULL,
  name text NOT NULL,
  qty_per_pack double precision NOT NULL,
  barcode text,
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  UNIQUE (product_id, name)
);

CREATE TABLE payment_allocations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payment_id bigint NOT NULL,
  order_id bigint,
  amount_toman bigint NOT NULL,
  created_at text NOT NULL
);

CREATE TABLE payments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  customer_id bigint NOT NULL,
  amount_toman bigint NOT NULL,
  method text NOT NULL CHECK (method IN ('CASH', 'POS', 'CARD_TO_CARD', 'CHEQUE', 'CREDIT_NOTE', 'OTHER')),
  received_at text NOT NULL,
  received_by bigint NOT NULL,
  reference text,
  receipt_photo_stem text,
  cheque_id bigint,
  delivery_stop_id bigint,
  note text,
  voided_at text,
  voided_by bigint,
  void_reason text,
  created_at text NOT NULL,
  client_uuid text
);

CREATE TABLE photos (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entity_type text NOT NULL CHECK (entity_type IN ('district', 'customer', 'payment')),
  entity_id bigint NOT NULL,
  file_stem text UNIQUE NOT NULL,
  caption text,
  taken_at text NOT NULL,
  created_at text NOT NULL
);

CREATE TABLE platform_access_log (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  platform_user_id bigint NOT NULL,
  organization_id bigint NOT NULL,
  path text NOT NULL,
  occurred_at text NOT NULL
);

CREATE TABLE product_costs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id bigint NOT NULL,
  packaging_id bigint,
  method text NOT NULL CHECK (method IN ('weighted_average', 'landed')),
  cost_toman bigint NOT NULL,
  valid_from text NOT NULL,
  created_by bigint,
  created_at text NOT NULL
);

CREATE TABLE product_prices (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id bigint NOT NULL,
  packaging_id bigint,
  price_toman bigint NOT NULL,
  valid_from text NOT NULL,
  created_by bigint,
  created_at text NOT NULL
);

CREATE TABLE products (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  sku text,
  base_unit text NOT NULL DEFAULT 'عدد',
  kg_per_base_unit double precision NOT NULL DEFAULT 0,
  avg_cost_toman bigint NOT NULL DEFAULT 0,
  active bigint NOT NULL DEFAULT 1,
  notes text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  reorder_point double precision,
  target_stock double precision,
  shelf_life_days bigint,
  organization_id bigint,
  volume_m3_per_base_unit double precision,
  UNIQUE (organization_id, sku)
);

CREATE TABLE purchase_lines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purchase_id bigint NOT NULL,
  product_id bigint NOT NULL,
  base_qty double precision NOT NULL,
  unit_cost_toman bigint NOT NULL,
  created_at text NOT NULL
);

CREATE TABLE purchases (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier text,
  supplier_id bigint,
  purchase_date text NOT NULL,
  invoice_no text,
  notes text,
  created_by bigint NOT NULL,
  created_at text NOT NULL,
  organization_id bigint
);

CREATE TABLE push_subscriptions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  endpoint text UNIQUE NOT NULL,
  p256dh text NOT NULL,
  auth text NOT NULL,
  created_at text NOT NULL,
  user_id bigint
);

CREATE TABLE quality_complaints (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  customer_id bigint,
  order_id bigint,
  product_id bigint,
  batch_id bigint,
  reported_at text NOT NULL,
  reported_by bigint,
  category text NOT NULL CHECK (category IN ('spoilage', 'packaging', 'foreign_object', 'short_weight', 'wrong_product', 'other')),
  severity text NOT NULL DEFAULT 'medium' CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  description text,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'resolved', 'dismissed')),
  resolution text,
  resolved_at text,
  resolved_by bigint,
  created_at text NOT NULL
);

CREATE TABLE reason_codes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint,
  domain text NOT NULL CHECK (domain IN ('delivery_fail', 'delivery_delay', 'order_cancel', 'order_return')),
  code text NOT NULL,
  label_fa text NOT NULL,
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  UNIQUE (organization_id, domain, code)
);

CREATE TABLE reminders (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entity_type text NOT NULL CHECK (entity_type IN ('district', 'customer')),
  entity_id bigint NOT NULL,
  due_date text NOT NULL,
  message text NOT NULL,
  resolved bigint NOT NULL DEFAULT 0,
  created_at text NOT NULL
);

CREATE TABLE representative_onboarding_steps (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  representative_id bigint NOT NULL,
  step_code text NOT NULL,
  label_fa text NOT NULL,
  required bigint NOT NULL DEFAULT 1,
  sort_order bigint NOT NULL DEFAULT 0,
  completed_at text,
  completed_by bigint,
  notes text,
  UNIQUE (representative_id, step_code)
);

CREATE TABLE representative_profiles (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  customer_id bigint NOT NULL,
  rep_code text NOT NULL,
  manager_user_id bigint,
  contract_signed_at text,
  contract_expires_at text,
  exclusivity_territory_id bigint,
  stage text NOT NULL DEFAULT 'prospect' CHECK (stage IN ('prospect','qualified','negotiating','documents','approved','onboarding','active','dormant','terminated')),
  activated_at text,
  first_order_at text,
  credit_terms_days bigint NOT NULL DEFAULT 0,
  discount_tier text,
  monthly_target_kg double precision,
  monthly_target_toman bigint,
  health_score double precision,
  health_computed_at text,
  notes text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (organization_id, customer_id),
  UNIQUE (organization_id, rep_code)
);

CREATE TABLE route_schedules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  route_template_id bigint NOT NULL,
  day_of_week bigint NOT NULL,
  start_time text,
  end_time text,
  cutoff_time text,
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  UNIQUE (route_template_id, day_of_week)
);

CREATE TABLE route_templates (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  territory_id bigint,
  default_driver_id bigint,
  default_vehicle_id bigint,
  max_stops bigint,
  max_weight_kg double precision,
  max_volume_m3 double precision,
  max_duration_min bigint,
  service_time_min bigint NOT NULL DEFAULT 8,
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (organization_id, code)
);

CREATE TABLE rule_runs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  rule_id bigint NOT NULL,
  entity_type text,
  entity_id bigint,
  fired_at text NOT NULL,
  cooldown_until text NOT NULL,
  task_id bigint,
  alert_id bigint,
  escalated_at text,
  resolved_at text
);

CREATE TABLE rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint,
  code text NOT NULL,
  name text NOT NULL,
  trigger_kind text NOT NULL,
  condition_json text,
  action_kind text NOT NULL CHECK (action_kind IN ('task', 'alert', 'notify')),
  action_json text,
  cooldown_min bigint NOT NULL DEFAULT 1440,
  escalate_after_min bigint,
  escalate_to_role text,
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (organization_id, code)
);

CREATE TABLE run_draft_stops (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  draft_id bigint NOT NULL,
  order_id bigint NOT NULL,
  seq bigint NOT NULL DEFAULT 0,
  created_at text NOT NULL,
  UNIQUE (draft_id, order_id)
);

CREATE TABLE run_drafts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  user_id bigint NOT NULL,
  driver_user_id bigint,
  run_date text,
  created_by_suggest bigint NOT NULL DEFAULT 0,
  manual_edits bigint NOT NULL DEFAULT 0,
  created_at text NOT NULL,
  updated_at text NOT NULL
);

CREATE TABLE run_facility_stops (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  role text NOT NULL CHECK (role IN ('load', 'unload')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'done')),
  done_at text,
  done_by bigint,
  notes text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (run_id, role)
);

CREATE TABLE run_unload_lines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id bigint NOT NULL,
  product_id bigint NOT NULL,
  disposition text NOT NULL CHECK (disposition IN ('returned', 'damaged', 'expired', 'discarded', 'lost', 'sample')),
  qty_base bigint NOT NULL,
  note text,
  occurred_at text NOT NULL,
  created_by bigint,
  created_at text NOT NULL
);

CREATE TABLE sales (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_no text,
  sale_date text NOT NULL,
  customer_name text NOT NULL,
  product_name text,
  qty double precision,
  amount double precision NOT NULL DEFAULT 0,
  payment_status text,
  shipping_status text,
  imported_at text NOT NULL,
  organization_id bigint
);

CREATE TABLE saved_locations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  maps_url text NOT NULL,
  address text,
  lat double precision,
  lng double precision,
  resolution text NOT NULL DEFAULT 'unresolved' CHECK (resolution IN ('direct', 'pluscode', 'browser', 'nominatim', 'manual', 'unresolved')),
  notes text,
  created_at text NOT NULL,
  status text,
  updated_at text,
  rating_potential bigint,
  rating_volume bigint,
  rating_ease bigint,
  group_id bigint,
  organization_id bigint,
  visit_outcome text,
  UNIQUE (organization_id, maps_url)
);

CREATE TABLE seasonal_factors (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint,
  kind text NOT NULL CHECK (kind IN ('month', 'dow')),
  idx bigint NOT NULL,
  factor double precision NOT NULL DEFAULT 1,
  note_fa text,
  updated_at text NOT NULL,
  UNIQUE (organization_id, kind, idx)
);

CREATE TABLE stock_movements (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  facility_id bigint NOT NULL,
  product_id bigint NOT NULL,
  batch_id bigint,
  base_qty double precision NOT NULL,
  kind text NOT NULL CHECK (kind IN ('PURCHASE_IN', 'TRANSFER_OUT', 'TRANSFER_IN', 'DELIVERY_OUT', 'SAMPLE_OUT', 'RETURN_IN', 'ADJUSTMENT', 'COUNT', 'WRITE_OFF')),
  ref_type text,
  ref_id bigint,
  occurred_at text NOT NULL,
  created_by bigint,
  notes text,
  created_at text NOT NULL
);

CREATE TABLE stock_reservations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  order_id bigint NOT NULL,
  order_line_id bigint NOT NULL,
  product_id bigint NOT NULL,
  batch_id bigint,
  base_qty double precision NOT NULL,
  released_at text,
  created_at text NOT NULL
);

CREATE TABLE suppliers (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  name text NOT NULL,
  phone text,
  notes text,
  active bigint NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_by bigint,
  created_at text NOT NULL
);

CREATE TABLE sync_mutations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  client_uuid text NOT NULL,
  user_id bigint,
  device_id text,
  op text NOT NULL,
  payload_json text NOT NULL,
  occurred_at text NOT NULL,
  clock_skew_ms bigint NOT NULL DEFAULT 0,
  received_at text NOT NULL,
  applied_at text,
  status text NOT NULL DEFAULT 'received' CHECK (status IN ('received', 'applied', 'duplicate', 'conflict', 'failed')),
  result_json text,
  error text,
  UNIQUE (organization_id, client_uuid)
);

CREATE TABLE targets (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  user_id bigint,
  group_id bigint,
  period text NOT NULL,
  metric text NOT NULL CHECK (metric IN ('revenue_toman', 'kg', 'orders')),
  target_value double precision NOT NULL,
  created_by bigint,
  created_at text NOT NULL,
  UNIQUE (organization_id, user_id, group_id, period, metric)
);

CREATE TABLE task_recurrences (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  title text NOT NULL,
  kind text NOT NULL,
  assignee_user_id bigint,
  role_hint text,
  group_id bigint,
  entity_type text,
  entity_id bigint,
  priority text NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('CRITICAL', 'HIGH', 'NORMAL', 'LOW')),
  rrule text NOT NULL,
  active bigint NOT NULL DEFAULT 1,
  last_spawned_on text,
  created_by bigint,
  created_at text NOT NULL,
  updated_at text NOT NULL
);

CREATE TABLE tasks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  assignee_user_id bigint,
  role_hint text,
  group_id bigint,
  kind text NOT NULL,
  title text NOT NULL,
  entity_type text,
  entity_id bigint,
  due_at text,
  priority text NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('CRITICAL', 'HIGH', 'NORMAL', 'LOW')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'done', 'dismissed')),
  outcome_code text,
  outcome_note text,
  created_by bigint,
  created_at text NOT NULL,
  done_at text,
  stage text,
  started_at text,
  snooze_count bigint NOT NULL DEFAULT 0
);

CREATE TABLE user_recovery_codes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  code_hash text NOT NULL,
  used_at text,
  created_at text NOT NULL
);

CREATE TABLE user_roles (
  user_id bigint NOT NULL,
  role text NOT NULL,
  PRIMARY KEY (user_id, role)
);

CREATE TABLE users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username text UNIQUE NOT NULL,
  password_hash text NOT NULL,
  display_name text NOT NULL,
  role text NOT NULL DEFAULT 'group_manager' CHECK (role IN ('platform_owner', 'owner', 'group_manager', 'rep_manager', 'phone_sales', 'field_rep', 'delivery_driver', 'salesperson', 'driver')),
  group_id bigint,
  organization_id bigint,
  staff_code text,
  phone text,
  active bigint NOT NULL DEFAULT 1,
  token_version bigint NOT NULL DEFAULT 0,
  location_consent_at text,
  created_at text NOT NULL,
  telegram_chat_id text,
  telegram_link_nonce text,
  avatar_url text,
  avatar_stem text,
  prefs_json text,
  totp_secret text,
  totp_enabled_at text,
  totp_last_step bigint,
  must_change_password bigint NOT NULL DEFAULT 0
);

CREATE TABLE vehicles (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id bigint NOT NULL,
  plate text,
  name text NOT NULL,
  driver_default_id bigint,
  max_weight_kg double precision,
  max_volume_m3 double precision,
  max_stops bigint,
  has_refrigeration bigint NOT NULL DEFAULT 0,
  cost_per_km_toman bigint NOT NULL DEFAULT 0,
  active bigint NOT NULL DEFAULT 1,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  facility_id bigint,
  UNIQUE (organization_id, plate)
);

CREATE TABLE visit_plans (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entity_type text NOT NULL CHECK (entity_type IN ('district', 'customer', 'facility', 'lead_location')),
  entity_id bigint NOT NULL,
  planned_date text NOT NULL,
  status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'done', 'skipped')),
  sort_order bigint NOT NULL DEFAULT 0,
  created_at text NOT NULL,
  purpose text
);

CREATE TABLE weather_snapshots (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  lat_r double precision NOT NULL,
  lng_r double precision NOT NULL,
  forecast_date text NOT NULL,
  temp_min double precision,
  temp_max double precision,
  precip_prob bigint,
  precip_mm double precision,
  snow_mm double precision,
  wind_kmh double precision,
  gust_kmh double precision,
  visibility_m bigint,
  weather_code bigint,
  fetched_at text NOT NULL,
  raw_json text,
  UNIQUE (lat_r, lng_r, forecast_date)
);

CREATE INDEX idx_activity_entity ON activity_log(entity_type, entity_id, created_at);
