CREATE INDEX idx_lead_list_items_list ON lead_list_items(list_id, sort_order);
CREATE INDEX idx_lead_run_stops_run ON lead_run_stops(run_id, sort_order);
CREATE INDEX idx_login_events_org ON login_events(organization_id, created_at);
CREATE INDEX idx_login_events_user ON login_events(user_id, created_at);
CREATE INDEX idx_manager_commission_payments_person ON manager_commission_payments(manager_user_id, paid_on);
CREATE INDEX idx_manager_overrides_lookup ON manager_commission_overrides(manager_user_id, valid_from);
CREATE INDEX idx_order_events_order ON order_events(order_id, id);
CREATE INDEX idx_order_lines_order ON order_lines(order_id);
CREATE INDEX idx_order_lines_product ON order_lines(product_id);
CREATE INDEX idx_orders_customer ON orders(customer_id, order_date);
CREATE INDEX idx_orders_salesperson ON orders(salesperson_user_id, order_date);
CREATE INDEX idx_orders_scope ON orders(group_id, status, order_date);
CREATE INDEX idx_packagings_product ON packagings(product_id);
CREATE INDEX idx_photos_entity ON photos(entity_type, entity_id, taken_at);
CREATE INDEX idx_product_costs_lookup ON product_costs(product_id, packaging_id, valid_from);
CREATE INDEX idx_product_prices_lookup ON product_prices(product_id, packaging_id, valid_from);
