CREATE INDEX idx_purchase_lines_purchase ON purchase_lines(purchase_id);
CREATE INDEX idx_purchases_date ON purchases(purchase_date);
CREATE INDEX idx_reminders_due ON reminders(resolved, due_date);
CREATE INDEX idx_run_draft_stops_draft ON run_draft_stops(draft_id, seq);
CREATE INDEX idx_run_drafts_user ON run_drafts(organization_id, user_id);
CREATE INDEX idx_run_facility_stops_run ON run_facility_stops(run_id, role);
CREATE INDEX idx_run_unload_lines_run ON run_unload_lines(run_id);
CREATE INDEX idx_sales_customer ON sales(customer_name, sale_date);
CREATE INDEX idx_sales_product ON sales(customer_name, product_name);
