INSERT INTO kpi_definitions (id, organization_id, metric, title_fa, definition_fa, formula_fa, owner_role, benchmark_fa, frequency, action_fa, tier, direction, updated_at) OVERRIDING SYSTEM VALUE VALUES
  (1, NULL, 'net_sales', 'فروش خالص', 'ارزش کالای تحویل‌شده در دورهٔ جاری، به قیمت فروش ثبت‌شده روی سطر سفارش، پس از کسر برگشتی.', 'Σ (تعداد تحویل‌شدهٔ هر سطر × قیمت واحد آن سطر) روی سفارش‌های تحویل‌شده', 'group_manager', 'رشد ماهانهٔ ۵٪ تا ۱۰٪ در سال اول', 'daily', 'اگر زیر هدف است، دکمهٔ «چرا؟» را بزنید و افت را تا سطح فروشنده و مرحلهٔ قیف دنبال کنید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (2, NULL, 'gross_profit', 'سود ناخالص', 'فروش خالص منهای بهای تمام‌شدهٔ کالای همان سفارش‌ها (از قیمت خرید سری ساخت).', 'فروش خالص − Σ (تعداد تحویل‌شده × بهای واحد سری ساخت)', 'owner', 'متناسب با حاشیهٔ هدف؛ نباید کندتر از فروش رشد کند', 'weekly', 'اگر فروش بالا می‌رود ولی سود نه، ترکیب فروش کالاها و تخفیف‌ها را در بخش «حاشیهٔ مشارکتی» بررسی کنید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (3, NULL, 'gross_margin', 'حاشیهٔ سود ناخالص', 'سهم سود ناخالص از فروش خالص، به‌صورت درصد.', 'سود ناخالص ÷ فروش خالص', 'owner', '۱۸٪ تا ۲۵٪ برای توزیع کره', 'weekly', 'افت حاشیه یعنی تخفیف زیاد یا رشد فروش کالای کم‌سود؛ سیاست قیمت و سبد فروشنده را مرور کنید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (4, NULL, 'orders', 'تعداد سفارش', 'شمار سفارش‌هایی که در دوره به وضعیت تحویل‌شده رسیده‌اند.', 'COUNT(سفارش‌های تحویل‌شده در دوره)', 'group_manager', 'روند صعودی هم‌راستا با تعداد مشتری فعال', 'daily', 'افت هم‌زمان با فروش یعنی مشکل تقاضا؛ افت بدون افت فروش یعنی سفارش‌ها بزرگ‌تر شده‌اند.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (5, NULL, 'aov', 'میانگین ارزش سفارش', 'فروش خالص دوره تقسیم بر تعداد سفارش تحویل‌شدهٔ همان دوره.', 'فروش خالص ÷ تعداد سفارش', 'group_manager', 'رشد آرام از طریق فروش مکمل، نه تخفیف حجمی', 'weekly', 'برای رشد، فروش مکمل (کارت فرصت در مرکز اقدام) را روی مشتری‌های تک‌کالا اجرا کنید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (6, NULL, 'active_customers', 'مشتری فعال', 'مشتری‌ای که در ۶۰ روز گذشته دست‌کم یک سفارش تأییدشده داشته است (تعریف واژه‌نامهٔ داده).', 'COUNT(مشتری با ≥۱ سفارش تأییدشده در ۶۰ روز اخیر)', 'group_manager', 'بیش از ۷۰٪ کل مشتری‌های ثبت‌شدهٔ منطقه', 'weekly', 'ریزش این عدد را با فهرست «مشتری در خطر» در مرکز اقدام تطبیق دهید و تماس بگیرید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (7, NULL, 'new_customers', 'مشتری جدید', 'مشتری‌ای که اولین سفارش تاریخ‌اش (نه اولین سفارش در بازهٔ گزارش) در این دوره است.', 'COUNT(مشتری با MIN(تاریخ سفارش) داخل دوره)', 'phone_sales', 'متناسب با تعداد نمونهٔ گذاشته‌شده و نرخ تبدیل نمونه', 'monthly', 'اگر کم است، تعداد نمونهٔ فعال و پیگیری نمونه را بررسی کنید؛ ورودی قیف مشکل دارد.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (8, NULL, 'lost_customers', 'مشتری از‌دست‌رفته', 'مشتری‌ای که ابتدای دوره فعال بوده و تا پایان دوره ۶۰ روز بدون سفارش مانده است.', 'COUNT(فعال در ابتدای دوره ∧ بدون سفارش در ۶۰ روز منتهی به پایان دوره)', 'group_manager', 'کمتر از ۵٪ پایگاه مشتری در ماه', 'monthly', 'هر مورد را به‌عنوان یک کار تماس به فروشندهٔ همان مشتری بسپارید و علت را در کد نتیجه ثبت کنید.', 1, 'down', '2026-01-01T00:00:00.000Z'),
  (9, NULL, 'repeat_rate', 'نرخ خرید تکرارشونده', 'سهم مشتری‌هایی که در دوره دست‌کم دو سفارش داشته‌اند از مشتری‌هایی که دست‌کم یک سفارش داشته‌اند.', 'COUNT(مشتری با ≥۲ سفارش در دوره) ÷ COUNT(مشتری با ≥۱ سفارش در دوره)', 'phone_sales', 'بیش از ۶۰٪ برای کالای مصرفی پرگردش', 'monthly', 'نرخ پایین یعنی مشکل کیفیت یا پیگیری؛ تماس روز تحویل و بازهٔ سفارش بعدی را جدی بگیرید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (10, NULL, 'collection_rate', 'نرخ وصول', 'نسبت مبلغ دریافت‌شده در دوره به ارزش کالای تحویل‌شدهٔ همان دوره.', 'Σ دریافت‌های دوره ÷ فروش خالص دوره', 'owner', 'بالای ۹۰٪؛ زیر ۸۰٪ یعنی خطر نقدینگی', 'weekly', 'با فهرست «مطالبات معوق» مرکز اقدام شروع کنید و چک‌های سررسیدشده را پیگیری کنید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (11, NULL, 'overdue_receivables', 'مطالبات معوق', 'جمع بدهی مشتریان که بیش از ۳۰ روز از تحویل سفارش پرداخت‌نشده مانده است، در پایان دوره.', 'Σ بدهی مشتری در سطل «بیش از ۳۰ روز»', 'owner', 'کمتر از ۱۰٪ کل مطالبات باز', 'weekly', 'سقف اعتبار مشتری‌های بدحساب را ببندید و تا تسویه، سفارش نقدی کنید.', 1, 'down', '2026-01-01T00:00:00.000Z'),
  (12, NULL, 'on_time_delivery', 'تحویل به‌موقع', 'سهم سفارش‌هایی که در تاریخ برنامه‌ریزی‌شده یا زودتر تحویل شده‌اند از کل سفارش‌های تحویل‌شده.', 'COUNT(تاریخ تحویل ≤ تاریخ برنامه) ÷ COUNT(تحویل‌شده)', 'group_manager', 'بالای ۹۵٪', 'daily', 'افت را با «امتیاز راننده» و شرایط جوی مسیر تطبیق دهید؛ ظرفیت مسیر را بازبینی کنید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (13, NULL, 'fulfillment_rate', 'نرخ تکمیل سفارش', 'سهم تعداد تحویل‌شده از تعداد سفارش‌داده‌شده، روی سفارش‌هایی که به مرحلهٔ قیمت‌گذاری رسیده‌اند.', 'Σ تعداد تحویل‌شدهٔ سطرها ÷ Σ تعداد سفارش‌دادهٔ سطرها', 'group_manager', 'بالای ۹۸٪ برای کالای موجود', 'daily', 'کسری مکرر یعنی مشکل موجودی یا بارگیری؛ هشدار کمبود موجودی و نرخ پرشدن راننده را ببینید.', 1, 'up', '2026-01-01T00:00:00.000Z'),
  (14, NULL, 'sample_conversion', 'نرخ تبدیل نمونه', 'سهم سفارش‌های نمونه که ظرف ۳۰ روز یک سفارش عادی از همان مشتری به دنبال داشته‌اند.', 'COUNT(نمونه با سفارش عادی بعدی ظرف ۳۰ روز) ÷ COUNT(سفارش نمونه)', 'phone_sales', 'بالای ۳۰٪', 'monthly', 'نرخ پایین یعنی پیگیری نمونه ضعیف است؛ کار «پیگیری نمونه» را سر وقت ببندید و کارت اعتراض را بخوانید.', 1, 'up', '2026-01-01T00:00:00.000Z');
SELECT setval(pg_get_serial_sequence('kpi_definitions', 'id'), (SELECT MAX(id) FROM kpi_definitions));

