INSERT INTO objection_cards (id, organization_id, outcome_code, customer_type, title_fa, script_fa, module_slug, active, updated_at) OVERRIDING SYSTEM VALUE VALUES
  (1, NULL, 'PRICE_OBJECTION', NULL, '«گران است»', 'قیمت را به مصرف هر پرس برگردانید: «کره در هر پرس حدود X تومان می‌شود؛ تفاوتش با مارک ارزان‌تر در ماه Y تومان است، اما برگشتی و شکایت مشتری شما را کم می‌کند.» بعد یک نمونهٔ رایگان پیشنهاد دهید.', '02-phone-sales', 1, '2026-01-01T00:00:00.000Z'),
  (2, NULL, 'NOT_INTERESTED', NULL, '«علاقه‌ای ندارم»', 'روی زمان‌بندی کار کنید، نه محصول: «کاملاً درست است، الان وقت خوبی نیست. اجازه بدهید فقط یک نمونه بگذارم و هفتهٔ بعد اگر خواستید یک تماس کوتاه بگیریم.» فشار نیاورید؛ در دفترچه یادداشت کنید و در بازهٔ بعدی برگردید.', '01-market-and-customer', 1, '2026-01-01T00:00:00.000Z'),
  (3, NULL, 'NO_TIME', NULL, '«الان وقت ندارم»', '«حتماً، ۳۰ ثانیه بیشتر نمی‌گیرم — فقط می‌خواستم بگویم این هفته نمونهٔ کره داریم؛ کی برای‌تان بیاورم، امروز یا فردا؟» یک انتخاب دوگزینه‌ای بدهید.', '02-phone-sales', 1, '2026-01-01T00:00:00.000Z'),
  (4, NULL, 'ALREADY_SUPPLIED', NULL, '«تأمین‌کننده دارم»', '«عالی است که یک تأمین‌کنندهٔ ثابت دارید. بیشتر مشتری‌های ما هم دارند و ما را برای روزهایی نگه می‌دارند که آن‌ها جنس ندارند یا دیر می‌رسانند. یک نمونه بگذارم که مقایسه دستتان باشد؟»', '01-market-and-customer', 1, '2026-01-01T00:00:00.000Z'),
  (5, NULL, 'QUALITY_DOUBT', NULL, '«کیفیتش را نمی‌شناسم»', 'روی قابلیت ردیابی تکیه کنید: «هر سری ساخت ما تاریخ تولید و انقضا دارد و ما دقیقاً می‌دانیم هر جعبه به کدام مغازه رفته. یک نمونه بگذارم، خودتان روی یک غذا امتحان کنید.»', '01-market-and-customer', 1, '2026-01-01T00:00:00.000Z'),
  (6, NULL, 'PAYMENT_TERMS', NULL, '«نقدی نمی‌خرم»', '«مشکلی نیست، برای مشتری‌های ثابت مهلت تسویه داریم. سفارش اول را نقد بگیریم که آشنا شویم، از سفارش دوم روی چک یا مهلت هفتگی می‌رویم.»', '02-phone-sales', 1, '2026-01-01T00:00:00.000Z'),
  (7, NULL, 'CONTACTED', NULL, 'پیگیری تماس بی‌نتیجه', 'یک تماس بدون سفارش، شکست نیست. تاریخ تماس بعدی را همین حالا در دفترچه بگذارید (۳ تا ۷ روز)، و یک بهانهٔ تماس تازه آماده کنید: نمونهٔ جدید، تخفیف مناسبتی، یا محصول تازه.', '02-phone-sales', 1, '2026-01-01T00:00:00.000Z'),
  (8, NULL, 'ORDERED', NULL, 'بعد از اولین خرید', 'روز تحویل یک تماس کوتاه بگیرید: «کره به دستتان رسید؟ راضی بودید؟» و بازهٔ سفارش بعدی را پیشنهاد بدهید. اولین خرید تازه شروع رابطه است.', '01-market-and-customer', 1, '2026-01-01T00:00:00.000Z');
