CREATE FUNCTION accounts_no_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'accounts is append-only: deactivate an account, do not delete it';
  RETURN OLD;
END $$;
CREATE TRIGGER accounts_no_delete BEFORE DELETE ON accounts FOR EACH ROW EXECUTE FUNCTION accounts_no_delete_fn();

CREATE FUNCTION activities_no_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
