CREATE FUNCTION order_lines_void_figures_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE orders SET kg_total = NULL, total_toman = NULL, cost_toman = NULL WHERE id = OLD.order_id;
  RETURN NULL;
END $$;
CREATE TRIGGER order_lines_void_figures_delete AFTER DELETE ON order_lines FOR EACH ROW EXECUTE FUNCTION order_lines_void_figures_delete_fn();

CREATE FUNCTION order_lines_void_figures_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE orders SET kg_total = NULL, total_toman = NULL, cost_toman = NULL WHERE id = NEW.order_id;
  RETURN NULL;
END $$;
CREATE TRIGGER order_lines_void_figures_insert AFTER INSERT ON order_lines FOR EACH ROW EXECUTE FUNCTION order_lines_void_figures_insert_fn();

CREATE FUNCTION order_lines_void_figures_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE orders SET kg_total = NULL, total_toman = NULL, cost_toman = NULL WHERE id IN (OLD.order_id, NEW.order_id);
  RETURN NULL;
END $$;
CREATE TRIGGER order_lines_void_figures_update AFTER UPDATE ON order_lines FOR EACH ROW EXECUTE FUNCTION order_lines_void_figures_update_fn();

CREATE FUNCTION user_roles_after_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO user_roles (user_id, role) VALUES (NEW.id, NEW.role) ON CONFLICT DO NOTHING;
  RETURN NULL;
END $$;
CREATE TRIGGER user_roles_after_insert AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION user_roles_after_insert_fn();

CREATE FUNCTION user_roles_after_update_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (SELECT COUNT(*) FROM user_roles WHERE user_id = NEW.id) <= 1 AND EXISTS (SELECT 1 FROM user_roles WHERE user_id = NEW.id AND role = OLD.role) THEN
    UPDATE user_roles SET role = NEW.role WHERE user_id = NEW.id;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER user_roles_after_update AFTER UPDATE OF role ON users FOR EACH ROW EXECUTE FUNCTION user_roles_after_update_fn();

